import React from 'react';

const EmptySlot = ({ index, circleBestiesLength, setShowShareModal, buttonRef }) => {
  const slotStyles = [
    { border: 'border-pink-500', text: 'text-pink-500', bg: 'bg-pink-500' },
    { border: 'border-purple-500', text: 'text-purple-500', bg: 'bg-purple-500' },
    { border: 'border-blue-500', text: 'text-blue-500', bg: 'bg-blue-500' },
    { border: 'border-green-500', text: 'text-green-500', bg: 'bg-green-500' },
    { border: 'border-orange-500', text: 'text-orange-500', bg: 'bg-orange-500' },
  ];

  const style = slotStyles[index] || slotStyles[0];

  const angle = (index * 72 - 90) * (Math.PI / 180);
  const radius = 45;
  const x = 50 + radius * Math.cos(angle);
  const y = 50 + radius * Math.sin(angle);

  return (
    <div
      className="absolute"
      style={{
        left: `${x}%`,
        top: `${y}%`,
        transform: 'translate(-50%, -50%)',
      }}
    >
      <button
        ref={buttonRef}
        onClick={() => setShowShareModal(true)}
        className={`w-14 h-14 md:w-16 md:h-16 border-[6px] border-dashed ${style.border} rounded-full flex flex-col items-center justify-center ${style.text} font-bold hover:scale-110 hover:bg-purple-50 transition-all shadow-lg hover:shadow-xl animate-pulse-slow relative group`}
        title="Add someone who has your back"
      >
        <span className="text-2xl">+</span>
        <span className="text-[8px] opacity-70 mt-0.5">Add</span>
        {/* Tooltip */}
        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 opacity-0 group-hover:opacity-100 transition-all duration-200 pointer-events-none z-20">
          <div className="bg-gradient-to-r from-purple-600 to-pink-600 text-white px-3 py-2 rounded-lg text-xs font-semibold whitespace-nowrap shadow-xl">
            {circleBestiesLength === 0 ? "Your first bestie ✨" : "Add another one 💜"}
            <div className="absolute left-1/2 -translate-x-1/2 top-full w-0 h-0 border-l-4 border-r-4 border-t-4 border-transparent border-t-pink-600"></div>
          </div>
        </div>
      </button>
    </div>
  );
};

export default EmptySlot;
